input_query:
PREFIX cmt: <http://cmt#>
SELECT ?conference ?name
WHERE {
	?conference a cmt:Conference ;
		cmt:name ?name .
}

output_query:
PREFIX  cmt:  <http://cmt#>

SELECT  ?conference ?name
WHERE
  { ?conference  a                  <http://conference#Conference> ;
              <http://conference#has_a_name>  ?name ;
              a                     cmt:Conference
  }

input_query:
PREFIX cmt: <http://cmt#>
SELECT ?paper ?title
WHERE {
	?paper a cmt:Paper ;
		cmt:title ?title .
}

output_query:
PREFIX  cmt:  <http://cmt#>

SELECT  ?paper ?title
WHERE
  { ?paper  a          <http://conference#Conference_contribution> ;
            cmt:title  ?title
  }

input_query:
PREFIX cmt: <http://cmt#>
SELECT ?paper
WHERE {
	?paper a cmt:Paper ;
		cmt:hasDecision ?decision .
	?decision a cmt:Acceptance .
}

PREFIX cmt: <http://cmt#>
SELECT ?paper
WHERE {
	?paper a cmt:Paper ;
		cmt:hasDecision ?decision .
	?decision a cmt:Rejection .
}

PREFIX cmt: <http://cmt#>
SELECT ?paper ?reviewer
WHERE {
	?paper cmt:assignedTo ?reviewer .
	?reviewer a cmt:Reviewer .
}

PREFIX cmt: <http://cmt#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?pcm ?maxPapers
WHERE {
	?pcm a cmt:ProgramCommitteeMember ;
		cmt:maxPapers ?maxPapers .
	FILTER (?maxPapers > 5)
}

PREFIX cmt: <http://cmt#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?conference
WHERE {
	?conference a cmt:Conference ;
		cmt:acceptsHardcopySubmissions "true"^^xsd:boolean .
}

PREFIX cmt: <http://cmt#>
SELECT DISTINCT ?email
WHERE {
	?person a cmt:Person ;
		cmt:email ?email .
}
ORDER BY ?email

output_query:
PREFIX  cmt:  <http://cmt#>

SELECT  ?authorName ?paperTitle
WHERE
  { ?author  <http://conference#contributes>  ?paper ;
             <http://conference#has_a_name>  ?authorName ;
             a                     cmt:Conference .
    ?paper   cmt:title             ?paperTitle
  }

input_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX cmt: <http://cmt#>

SELECT ?conference ?name ?date ?reviewsPerPaper
WHERE {
  ?conference rdf:type cmt:Conference .
  ?conference cmt:name ?name ;
              cmt:date ?date ;
              cmt:reviewsPerPaper ?reviewsPerPaper .
}

output_query:
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  cmt:  <http://cmt#>

SELECT  ?conference ?name ?date ?reviewsPerPaper
WHERE
  { ?conference  rdf:type           <http://conference#Conference> ;
              <http://conference#has_a_name>  ?name ;
              rdf:type              cmt:Conference ;
              cmt:date              ?date ;
              cmt:reviewsPerPaper   ?reviewsPerPaper
  }

input_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX cmt: <http://cmt#>

SELECT ?metaReviewer ?email
WHERE {
  ?metaReviewer rdf:type cmt:Meta-Reviewer ;
                cmt:email ?email .
}

output_query:
SELECT DISTINCT  ?s
WHERE
  {   { ?s  a  <http://confOf#Country>}
    UNION
      { ?s  a  <http://confOf#City>}
  }

input_query:
PREFIX gbo: <http://gbo#>
SELECT ?cruise ?vesselName
WHERE {
	?cruise a gbo:Cruise ;
		gbo:hasVessel ?vessel .
	?vessel gbo:hasTitle ?vesselName .
}

PREFIX gbo: <http://gbo#>
SELECT ?cruise ?startPortName ?endPortName
WHERE {
	?cruise gbo:hasStartPortCall ?startCall ;
		gbo:hasEndPortCall ?endCall .
	?startCall gbo:atPort ?startPlace .
	?endCall gbo:atPort ?endPlace .
	?startPlace gbo:hasTitle ?startPortName .
	?endPlace gbo:hasTitle ?endPortName .
}

PREFIX gbo: <http://gbo#>
SELECT DISTINCT ?email
WHERE {
	?person a gbo:Person ;
		gbo:hasEmailAddress ?email .
}
ORDER BY ?email

PREFIX gbo: <http://gbo#>
SELECT ?sample ?feature
WHERE {
	?sample a gbo:PhysicalSample ;
		gbo:originatesFrom ?feature .
	?feature a gbo:Feature .
}

PREFIX gbo: <http://gbo#>
SELECT ?organization ?award
WHERE {
	?organization gbo:isSponsorOf ?award .
	?award a gbo:Award .
}

PREFIX gbo: <http://gbo#>
SELECT ?person ?affiliation
WHERE {
	?person a gbo:Person ;
		gbo:hasAffiliation ?affiliation .
	?affiliation a gbo:Organization .
}

PREFIX gbo: <http://gbo#>
SELECT ?entity ?title
WHERE {
	{ ?entity a gbo:Dataset . }
	UNION
	{ ?entity a gbo:Document . }
	?entity gbo:hasTitle ?title .
}

output_query:
PREFIX  gbo:  <http://gbo#>

SELECT  ?entity ?title
WHERE
  {   { ?entity  a  gbo:Dataset }
    UNION
      { ?entity  a  gbo:Document }
    ?entity  <http://gmo#hasCanonicalName>  ?title
  }

input_query:
PREFIX gbo: <http://gbo#>
SELECT ?person ?familyName
WHERE {
	?person a gbo:Person ;
		gbo:hasFamilyName ?familyName .
	FILTER regex(?familyName, "Smith", "i")
}

PREFIX gbo: <http://gbo#>
SELECT ?program ?sponsor
WHERE {
	?program a gbo:Program ;
		gbo:hasAward ?award .
	?award gbo:hasSponsor ?sponsor .
}

PREFIX gbo: <http://gbo#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?cruise ?startDate
WHERE {
	?cruise a gbo:Cruise ;
		gbo:hasStartDate ?startDate .
	FILTER (?startDate > "2010-01-01T00:00:00"^^xsd:dateTime)
}
